    "no-owner": "owner-enablement",
    "no-domains": "owner-enablement",
    "no-jurisdiction": "jurisdiction",
    "weak-jurisdiction": "jurisdiction",
    "expired": "jurisdiction",
    "no-context": "context",
    "no-renewal": "context"
